mutation CreateUser($input: CreateUserInput!) {
  createUser(input: $input) {
    success
    errors { code message }
    data { id }
    cascade {
      updated {
        typename
        id
        operation
        entity {
          __typename
          id
          ... on User { name email postCount }
          ... on Post { title published }
        }
      }
      deleted { typename id deletedAt }
      invalidations { queryName arguments strategy scope }
      typeInvalidations { typename affectedCount }
      metadata { timestamp depth affectedCount truncated }
    }
  }
}
